<template><div><div class="page-head"><div><span>WUJiaxin Integration / Knowledge</span><h2>FMECA 故障知识库</h2><p>已将成员项目中的典型故障模式以统一 PHM 接口接入。</p></div><el-input v-model="keyword" clearable placeholder="搜索部件、故障或原因" style="width:280px" /></div><el-card shadow="never"><el-table :data="filtered" stripe><el-table-column prop="id" label="序号" width="70"/><el-table-column prop="component" label="部件" width="140"/><el-table-column prop="fault_name" label="故障模式" width="160"/><el-table-column prop="fault_prob" label="故障概率" width="110"/><el-table-column prop="fault_reason" label="可能原因" min-width="220"/><el-table-column label="危害等级" width="110"><template #default="s"><el-tag :type="s.row.degree_harm.includes('Ⅰ')?'danger':'warning'">{{s.row.degree_harm}}</el-tag></template></el-table-column></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted}from'vue';const rows=ref([]),keyword=ref('');onMounted(async()=>{rows.value=(await(await fetch('/api/v1/integrations/wujiaxin/fmeca/')).json()).results||[]});const filtered=computed(()=>{const k=keyword.value.trim().toLowerCase();return k?rows.value.filter(r=>Object.values(r).join(' ').toLowerCase().includes(k)):rows.value});</script>
